mapper.select:
select
    ,
    u.nick_name as user_nick_name,
    u.avatar    as user_avatar,
    u.show_vip  as user_show_vip,
    g.name      as group_name
from apply_order o
left join app_user u on u.id = o.user_id and u.del_flag = '0'
left join apply_group g on g.id = o.group_id and g.del_flag = '0'
where o.del_flag = '0'

    and o.id = #{bo.id}


    and o.user_id = #{bo.userId}


    and u.nick_name like concat('%', #{bo.nickName}, '%')


    and o.title like concat('%', #{bo.title}, '%')


    and o.status = #{bo.status}


    and o.visibility = #{bo.visibility}


    and o.audit_status = #{bo.auditStatus}


    and o.group_id = #{bo.groupId}


    and o.is_top = #{bo.isTop}


    and o.create_time >= #{bo.beginTime}


    and o.create_time <= #{bo.endTime}

order by o.is_top desc, o.create_time desc
